// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Anton');

// Load the high-impact condensed sans-serif font at module level
const { fontFamily } = loadFont();



export type BulletListAnimationProps = Record<string, any>;

const BulletListAnimation: React.FC<BulletListAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  
  row1Line1 = "HOW MUCH CAPITAL YOU WANT TO RAISE",
  color1 = "#FF4E11",
  
  row2Line1 = "WHO YOU WANT TO RAISE FROM",
  color2 = "#FFCC00",
  
  row3Line1 = "HOW YOU PLAN TO MARKET THE OPPORTUNITY",
  color3 = "#4DD0E1",
  
  fontSizeSlider = 92,
  bulletSizeSlider = 38,
  staggerFrames = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive calculations based on canvas dimensions
  const responsiveFontSize = (fontSizeSlider / 1080) * height;
  const responsiveBulletSize = (bulletSizeSlider / 1080) * height;

  // Track active row for dynamic background glow coordinates
  const glowY = interpolate(
    frame,
    [0, staggerFrames, staggerFrames * 2],
    [22, 50, 78],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dynamic glow color based on which step is active
  const glowColor = interpolateColors(
    frame,
    [staggerFrames * 0.5, staggerFrames * 1.5, staggerFrames * 2.5],
    [
      `${color1}1d`, // ~11% opacity hex-like color representation
      `${color2}1d`,
      `${color3}1d`
    ]
  );

  // Background style configuration
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const bgStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    backgroundImage: transparentBackground 
      ? "none" 
      : `radial-gradient(circle at 12% ${glowY}%, ${glowColor} 0%, rgba(10, 10, 10, 0) 55%), radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.02) 0%, rgba(0, 0, 0, 0) 100%)`,
    transition: "none",
  };

  // Safe container styles matching reference framing
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    height: "100%",
    paddingLeft: width * 0.08,
    paddingRight: width * 0.08,
    fontFamily,
    transition: "none",
  };

  // Helper to split text dynamically so specified parts are colored white
  const splitLineText = (text: string) => {
    const targets = ["HOW MUCH CAPITAL", "WHO YOU WANT", "HOW YOU PLAN"];
    for (const target of targets) {
      const index = text.toUpperCase().indexOf(target.toUpperCase());
      if (index !== -1) {
        const prefix = text.substring(0, index);
        const highlight = text.substring(index, index + target.length);
        const suffix = text.substring(index + target.length);
        return { prefix, highlight, suffix };
      }
    }
    return { prefix: "", highlight: "", suffix: text };
  };

  // Render a single high-impact row with masked sliding text and bouncy bullet
  const renderRow = (
    index: number,
    line1: string,
    color: string
  ) => {
    const rowStart = index * staggerFrames;

    // Bullet Snappy Entrance Spring
    const bulletSpring = spring({
      frame: frame - rowStart,
      fps,
      config: {
        damping: 11,
        mass: 0.5,
        stiffness: 95,
      },
    });

    const bulletScale = bulletSpring;
    const bulletX = interpolate(bulletSpring, [0, 1], [-60, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    // Elegant text slide up mask
    const line1Y = interpolate(frame - rowStart - 6, [0, 14], [105, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const line1Opacity = interpolate(frame - rowStart - 6, [0, 10], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    // Slight text container drift coordinates
    const textDriftX = interpolate(bulletSpring, [0, 1], [-20, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    // Parse text to identify highlight targets (making them white)
    const { prefix, highlight, suffix } = splitLineText(line1);

    // Calculate a safe font size scaling factor if the text is particularly long
    const textLength = line1.length;
    const lengthScale = textLength > 30 ? Math.max(0.6, 30 / textLength) : 1;
    const finalFontSize = responsiveFontSize * lengthScale;

    return (
      <div
        key={index}
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          marginTop: height * 0.035,
          marginBottom: height * 0.035,
          transition: "none",
        }}
      >
        {/* Bullet Dot */}
        <div
          style={{
            width: responsiveBulletSize,
            height: responsiveBulletSize,
            borderRadius: "50%",
            backgroundColor: color,
            marginRight: width * 0.045,
            transform: `scale(${bulletScale}) translateX(${bulletX}px)`,
            flexShrink: 0,
            boxShadow: `0 0 ${responsiveBulletSize * 0.4}px ${color}33`,
            transition: "none",
          }}
        />

        {/* Masked Typography Line */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            transform: `translateX(${textDriftX}px)`,
            transition: "none",
          }}
        >
          {/* Line Container */}
          <div
            style={{
              height: finalFontSize * 1.25,
              overflow: "hidden",
              display: "flex",
              alignItems: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                transform: `translateY(${line1Y}%)`,
                opacity: line1Opacity,
                fontSize: finalFontSize,
                lineHeight: 1,
                letterSpacing: "0.01em",
                textTransform: "uppercase",
                whiteSpace: "nowrap",
                transition: "none",
              }}
            >
              {prefix && <span style={{ color }}>{prefix}</span>}
              {highlight && <span style={{ color: "#ffffff" }}>{highlight}</span>}
              {suffix && <span style={{ color }}>{suffix}</span>}
              {!prefix && !highlight && !suffix && <span style={{ color }}>{line1}</span>}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Subtle continuous push-in scale for a cinematic feel
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0.98, 1.02],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={bgStyle}>
      <div
        style={{
          ...containerStyle,
          transform: `scale(${globalScale})`,
        }}
      >
        {renderRow(0, row1Line1, color1)}
        {renderRow(1, row2Line1, color2)}
        {renderRow(2, row3Line1, color3)}
      </div>
    </AbsoluteFill>
  );
};

export default BulletListAnimation;